create or replace function public.store_accounts_member_lookup(p_token text,p_member_id text) returns table(id uuid,voucher_no text,entry_date date,entry_type text,category text,party_type text,party_id text,party_name text,amount numeric,total_amount numeric,paid_amount numeric,due_amount numeric,due_date date,payment_status text,payment_method text,reference_no text,description text,entry_source text,display_group text,base_salary numeric,member_name text) language plpgsql security definer set search_path=public as $$ declare v_salary numeric:=0;v_name text;v_type text;begin if not public.store_accounts_has_permission(p_token,'dashboard') then raise exception 'Accounts permission required';end if;v_salary:=public.store_get_member_salary(trim(p_member_id));select full_name,'teacher' into v_name,v_type from public.teacher_members where lower(trim(member_id))=lower(trim(p_member_id)) limit 1;if v_name is null then select full_name,'staff' into v_name,v_type from public.staff_members where lower(trim(member_id))=lower(trim(p_member_id)) limit 1;end if;if v_name is null then select full_name,'accounts' into v_name,v_type from public.account_members where lower(trim(member_id))=lower(trim(p_member_id)) limit 1;end if;return query select e.id,e.voucher_no,e.entry_date,e.entry_type,e.category,e.party_type,e.party_id,e.party_name,e.amount,coalesce(e.total_amount,e.amount),coalesce(e.paid_amount,0),greatest(coalesce(e.total_amount,e.amount)-coalesce(e.paid_amount,0),0),e.due_date,coalesce(e.payment_status,case when coalesce(e.paid_amount,0)>=coalesce(e.total_amount,e.amount) then 'paid' else 'due' end),e.payment_method,e.reference_no,e.description,e.entry_source,case when e.entry_type='salary' and e.entry_source='salary_sheet' then 'salary_sheet' else 'old_due' end,v_salary,coalesce(e.party_name,v_name) from public.accounts_entries e where lower(trim(e.party_id))=lower(trim(p_member_id)) and e.status='posted' order by e.entry_date desc,e.created_at desc limit 200;end;$$;
grant execute on function public.store_accounts_member_lookup(text,text) to authenticated;